-- Run after the existing LinguaX schema. This file only inserts records; it does not alter tables.

select id, 'Choose the correct sentence.', '["She study every day.","She studies every day.","She studying every day.","She studied every day now."]'::jsonb, 'She studies every day.', 'With she, use studies in the present simple.' from public.lessons where title = 'Present Simple Essentials'
union all select id, 'Which form describes an action happening now?', '["I work.","I am working.","I worked.","I have work."]'::jsonb, 'I am working.', 'Present continuous uses am/is/are plus -ing.' from public.lessons where title = 'Present Continuous'
union all select id, 'Choose the past simple form.', '["go","went","gone","going"]'::jsonb, 'went', 'Went is the past simple of go.' from public.lessons where title = 'Past Simple'
union all select id, 'Complete: I ___ finished my homework.', '["has","have","am","did"]'::jsonb, 'have', 'Use have with I in present perfect.' from public.lessons where title = 'Present Perfect'
union all select id, 'Complete: If it rains, we ___ home.', '["stay","will stay","stayed","would stay"]'::jsonb, 'will stay', 'First conditional uses will in the result clause.' from public.lessons where title = 'Conditionals Zero and First'
union all select id, 'Which is passive voice?', '["People build houses.","Houses are built.","People are build houses.","Houses build people."]'::jsonb, 'Houses are built.', 'Passive voice is be plus past participle.' from public.lessons where title = 'Passive Voice'
union all select id, 'Choose the correct agreement.', '["The list are long.","The list is long.","The list be long.","The list were long."]'::jsonb, 'The list is long.', 'List is singular, so use is.' from public.lessons where title = 'Subject-Verb Agreement'
union all select id, 'Which word is closest to necessary?', '["optional","essential","rare","ordinary"]'::jsonb, 'essential', 'Essential means necessary.' from public.lessons where title = 'Synonyms for TOEFL'
union all select id, 'Complete: Scientists ___ research.', '["do","conduct","make","build"]'::jsonb, 'conduct', 'Conduct research is a common academic collocation.' from public.lessons where title = 'Academic Collocations'
union all select id, 'What is the main idea?', '["A minor example","The central message","A new vocabulary word","The author name"]'::jsonb, 'The central message', 'The main idea is the author’s central message.' from public.lessons where title = 'Reading Main Ideas'
union all select id, 'What should you find first in a structure question?', '["The longest word","Subject and verb","The final punctuation","A synonym"]'::jsonb, 'Subject and verb', 'Finding subject and verb reveals the sentence structure.' from public.lessons where title = 'TOEFL Structure Strategy';

select id, 'Which word often signals a contrast in a lecture?', '["Because","However","Therefore","For example"]'::jsonb, 'However', 'However introduces contrasting information.' from public.lessons where title = 'TOEFL Listening Strategy'
union all select id, 'What is a good TOEFL speaking response structure?', '["State, support, summarize","Question, memorize, repeat","Read, translate, stop","Only give an example"]'::jsonb, 'State, support, summarize', 'A direct opinion, support, and short summary creates a clear answer.' from public.lessons where title = 'TOEFL Speaking Foundations';

on conflict (name) do nothing;

